export interface ScreenCurve {
	t: number[];
	rule: (number | null)[];
	hold: (number | null)[];
}

export interface ScreenTrial {
	h: number;
	curve?: ScreenCurve | null;

export const leadTrial = (f: ScreenFeature) => f.trials.find((t) => t.h === f.lead_h) ?? f.trials[0];

/** Trial for horizon `h`; "lead" and any horizon the feature lacks fall back to the lead trial. */
export function trialAt(f: ScreenFeature, h: "lead" | number): ScreenTrial {
	if (h === "lead") return leadTrial(f);
	return f.trials.find((t) => t.h === h) ?? leadTrial(f);
}

/** Round chart ticks between `min` and `max`, anchored at 0 so a tick always lands on zero when in range. */
export function niceTicks(min: number, max: number): number[] {
	if (!Number.isFinite(min) || !Number.isFinite(max)) return [];
	const lo = Math.min(min, max);
	const hi = Math.max(min, max);
	if (lo === hi) return [lo];
	const raw = (hi - lo) / 5;
	const power = 10 ** Math.floor(Math.log10(raw));
	const norm = raw / power;
	const step = (norm < 1.5 ? 1 : norm < 3 ? 2 : norm < 7 ? 5 : 10) * power;
	const ticks: number[] = [];
	for (let v = Math.ceil(lo / step) * step; v <= Math.floor(hi / step) * step + 1e-9; v += step) {
		ticks.push(Number(v.toFixed(10)));
	}
	return ticks;
}

/** UTC date as `YYYY.MM.DD` (dots, so a day `01` never reads as a January `-01` tick). */
export function dateLabel(ts: number): string {
	const d = new Date(ts);
	const pad = (n: number) => String(n).padStart(2, "0");
	return `${d.getUTCFullYear()}.${pad(d.getUTCMonth() + 1)}.${pad(d.getUTCDate())}`;
}

export interface CurveView {
	rule: number[];
	hold: number[];
	ticks: number[];
	labels: string[];
}

/** Cumulative-return curve in percent; a missing point carries over the previous value. */
export function curveView(trial: ScreenTrial | null | undefined): CurveView | null {
	const curve = trial?.curve;
	if (!curve || !curve.t || curve.t.length < 2) return null;
	const carry = (values: (number | null)[] | undefined): number[] => {
		let last = 0;
		return (values ?? []).map((v) => {
			if (v == null || !Number.isFinite(v)) return last;
			last = v * 100;
			return last;
		});
	};
	const rule = carry(curve.rule);
	const hold = carry(curve.hold);
	const values = [...rule, ...hold];
	return {
		rule,
		hold,
		ticks: niceTicks(Math.min(0, ...values), Math.max(0, ...values)),
		labels: curve.t.map(dateLabel),
	};
}

export interface ScreenRuleTile {
	id: string;
	group: "entry" | "fill" | "exit";
	name: string;
	label: string;
	tip: string;
}

/** The screen's trade rule as tiles: indicator, direction, (regime gate), fill cost and holding horizon. */
export function screenRule(doc: ScreenDoc, feature: ScreenFeature, trial: ScreenTrial): ScreenRuleTile[] {
	const fixed = doc.fixed_sign != null;
	const sign = fixed ? doc.fixed_sign! : trial.train_sign;
	const signs = new Set(trial.folds.map((f) => f.train_sign));
	const changed = !fixed && signs.size > 1;
	const tiles: ScreenRuleTile[] = [
		{
			id: "indicator",
			group: "entry",
			name: featureName(feature),
			label: feature.tradeable === false ? "참고 지표" : "지표",
			tip:
				feature.tradeable === false
					? "그의 체결은 실시간으로 공개되지 않는다. 따라갈 수 있었다면 어땠나를 보는 참고 행이다."
					: (featureDef(feature) ?? feature.feature),
		},
		{
			id: "direction",
			group: "entry",
			name: sign >= 0 ? "기준 위면 롱" : "기준 위면 숏",
			label: changed ? "부호 바뀜" : sign >= 0 ? "순방향" : "역추세",
			tip: fixed
				? `부호 ${sign >= 0 ? "+" : "−"}${Math.abs(sign)}로 고정: 학습 구간 중앙값 위는 ${sign >= 0 ? "사고" : "파는"} 규칙이다.`
				: changed
					? "연도마다 학습 부호가 바뀌었다: 같은 지표라도 해마다 반대 방향을 가리킨다."
					: `학습 부호 ${sign >= 0 ? "+" : "−"}${Math.abs(sign)}: 학습 구간 중앙값 위는 ${sign >= 0 ? "사고" : "파는"} 규칙이다.`,
		},
	];
	if (doc.regime === "down") {
		tiles.push({
			id: "regime",
			group: "entry",
			name: "하락장만",
			label: "레짐 게이트",
			tip: "종가가 200일 평균 아래인 날만 점수를 매기고 매매한다.",
		});
	}
	const bp = Math.round(doc.cost_per_side * 1e4 * 10) / 10;
	tiles.push(
		{
			id: "fill",
			group: "fill",
			name: `편도 ${Number.isInteger(bp) ? bp : bp.toFixed(1)}bp`,
			label: "체결 비용",
			tip: `편도 ${(doc.cost_per_side * 1e4).toFixed(0)}bp(보수적 2배)와 실제 펀딩을 빼 계산했다.`,
		},
		{
			id: "hold",
			group: "exit",
			name: `${trial.h}${doc.unit} 보유`,
			label: "보유 기간",
			tip: `진입 후 ${trial.h}${doc.unit} 동안 들고 시계가 끝나면 청산한다.`,
		},
	);
	return tiles;
}

